// HasCanvas applies the HasEdge predicate on the "canvas" edge.
func HasCanvas() predicate.CanvasGenerationRun {
	return predicate.CanvasGenerationRun(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CanvasTable, CanvasColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCanvasWith applies the HasEdge predicate on the "canvas" edge with a given conditions (other predicates).
func HasCanvasWith(preds ...predicate.CreativeCanvas) predicate.CanvasGenerationRun {
	return predicate.CanvasGenerationRun(func(s *sql.Selector) {
		step := newCanvasStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CanvasGenerationRun) predicate.CanvasGenerationRun {
	return predicate.CanvasGenerationRun(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CanvasGenerationRun) predicate.CanvasGenerationRun {
	return predicate.CanvasGenerationRun(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CanvasGenerationRun) predicate.CanvasGenerationRun {
	return predicate.CanvasGenerationRun(sql.NotPredicates(p))
}
